'use strict';
const cityExperience=EldoriaExperienceModel;
cityExperience.ensure(state);
const expCSS=document.createElement('link');expCSS.rel='stylesheet';expCSS.href='city-experience.css?v=1';document.head.append(expCSS);
let expSceneSerial=0;
const expStoryBefore=lifeStoryScene;
lifeStoryScene=function(){const step=cityStory.ensure(state).step;if(cityExperience.cases[step]&&!cityExperience.canAdvance(state,step)&&cityStory.at(state,lifeWhere())){expInvestigate(step);return}expStoryBefore();if(cityExperience.cases[step])action('Revisit the investigation',()=>expInvestigate(step))};
function expInvestigate(step){if(cityStory.ensure(state).step!==step||!cityStory.at(state,lifeWhere())){lifeContinue();return}const c=cityExperience.cases[step],saved=cityExperience.progress(state,step),serial=++expSceneSerial;modal(c.title,'<span class="city-eyebrow">HANDS-ON INVESTIGATION · '+saved.found.length+'/3 OBJECTS EXAMINED</span><p>'+lifeEsc(c.intro)+'</p><div id="expSearch" class="exp-search" aria-label="Search the photographic room"><img src="assets/interiors/'+c.image+'.jpg" alt="'+lifeEsc(c.title)+'"><div id="expSearchObjects"></div></div><p id="expObjectNote" role="status">Look for the small glints. Use “Show search areas” whenever you want a hint. Every object is also reachable with the keyboard.</p><button id="expShowAreas">Show search areas</button><h3>Your evidence</h3><div id="expEvidence" class="exp-evidence"></div><h3>'+lifeEsc(c.prompt)+'</h3><p id="expOrder" aria-live="polite"></p><p id="expFeedback" role="status"></p><div id="expArrange" class="exp-arrange"></div>');
const evidence=$('expEvidence');c.clues.forEach(v=>{const b=document.createElement('button');b.className='exp-search-object'+(saved.found.includes(v.id)?' examined':'');b.dataset.object=v.id;b.setAttribute('aria-label','Examine '+v.label);b.style.left=v.x+'%';b.style.top=v.y+'%';b.innerHTML='<span aria-hidden="true">'+(saved.found.includes(v.id)?'✓':'✧')+'</span><small>'+lifeEsc(v.label)+'</small>';b.onclick=()=>{if(serial!==expSceneSerial||!$('modal').contains(b))return;const r=cityExperience.find(state,step,v.id,lifeWhere());if(!r.ok)return;persist();expInvestigate(step);$('expObjectNote').textContent=r.text;$('expObjectNote').focus()};$('expSearchObjects').append(b);const note=document.createElement('article');note.innerHTML='<strong>'+(saved.found.includes(v.id)?'✓ '+lifeEsc(v.label):'Unexamined object')+'</strong><p>'+lifeEsc(saved.found.includes(v.id)?v.text:'Search the room to reveal this evidence.')+'</p>';evidence.append(note)});$('expObjectNote').tabIndex=-1;
$('expShowAreas').onclick=()=>{$('expSearch').classList.toggle('show-areas');$('expShowAreas').textContent=$('expSearch').classList.contains('show-areas')?'Hide search areas':'Show search areas'};
let arranged=[];const update=()=>{$('expOrder').textContent=arranged.map(id=>c.clues.find(v=>v.id===id).label).join(' → ')};c.clues.forEach(v=>{const b=document.createElement('button');b.textContent=v.label;b.dataset.arrange=v.id;b.disabled=!saved.found.includes(v.id);b.onclick=()=>{if(arranged.includes(v.id))return;arranged.push(v.id);b.disabled=true;update()};$('expArrange').append(b)});
action('Clear evidence order',()=>{arranged=[];update();$('expArrange').querySelectorAll('button').forEach(b=>b.disabled=!saved.found.includes(b.dataset.arrange))});action('Connect the evidence',()=>{const r=cityExperience.assemble(state,step,arranged,lifeWhere());if(!r.ok){$('expFeedback').textContent=r.reason;return}lifeCommit();modal('The pieces fit','<p class="life-dialogue">'+lifeEsc(r.text)+'</p><p>You have connected this scene’s evidence. Now decide what to do with it.</p>');action('Continue this story scene',lifeStoryScene)});action('Pause investigation',()=>{$('modal').close();cityDraw()});}
const expBeats=[
{image:'festival',eyebrow:'PROLOGUE · THE EIGHTH LANTERN',title:'One song. A missing line.',text:'You arrive in Eldoria as seven lanterns rise above the festival. An eighth stays dark. A singer stops halfway through a lullaby.',voice:'Aurelia',line:'“We sing it every year. No one remembers how it ends.”'},
{image:'festival',eyebrow:'A VOICE IN THE CROWD',title:'Eight names were taken.',text:'A young man turns at the melody. Across the square, a healer drops her cup. Neither knows why the song feels like home.',voice:'The stranger',line:'“I know that tune. Someone used to sing it to us… before the wagon.”'},
{image:'library',eyebrow:'LATER · THE ROYAL ARCHIVE',title:'The book opens for you.',text:'Orren leads you to a book stitched with silver. Its blank pages fill with eight names. A single thread pulls toward a sealed festival register.',voice:'Orren',line:'“It has been silent for years. Why is it calling now?”'},
{image:'library',eyebrow:'YOUR STORY BEGINS',title:'Find the road they lost.',text:'Someone separated eight siblings and buried their names. Follow the records, uncover the missing memories, and help them choose their own road home.',voice:'The awakened book',line:'“Eight were lost beneath eight lanterns. Eight must choose their own road home.”'}
];
let expNarration=null;
function expStopVoice(){if(expNarration){window.speechSynthesis?.cancel();expNarration=null}}
function expOpening(index=0){$('modal').close();expStopVoice();let d=$('expOpening');if(!d){d=document.createElement('dialog');d.id='expOpening';d.setAttribute('aria-labelledby','expOpeningTitle');document.body.append(d);d.addEventListener('cancel',e=>{e.preventDefault();expFinishOpening(false)});d.addEventListener('close',expStopVoice)}const beat=expBeats[index];d.innerHTML='<div class="exp-film-art" style="background-image:url(assets/interiors/'+beat.image+'.jpg)"></div><div class="exp-film-shade"></div><section class="exp-film-text"><span class="city-eyebrow">'+lifeEsc(beat.eyebrow)+'</span><h1 id="expOpeningTitle">'+lifeEsc(beat.title)+'</h1><p>'+lifeEsc(beat.text)+'</p><blockquote><small>'+lifeEsc(beat.voice)+'</small>'+lifeEsc(beat.line)+'</blockquote><p class="exp-film-count">'+(index+1)+' / '+expBeats.length+' · Continue at your own pace</p><div class="exp-film-buttons"><button id="expFilmNext">'+(index<3?'Continue →':'Begin the investigation')+'</button><button id="expFilmSkip">Skip opening</button><button id="expFilmListen">Read scene aloud</button></div></section>';if(!d.open)d.showModal();$('expFilmNext').onclick=()=>index<3?expOpening(index+1):expFinishOpening(true);$('expFilmSkip').onclick=()=>expFinishOpening(false);$('expFilmListen').onclick=()=>{expStopVoice();if(!window.speechSynthesis||!window.SpeechSynthesisUtterance){$('expFilmListen').textContent='Reading aloud is unavailable';return}expNarration=new SpeechSynthesisUtterance(beat.text+' '+beat.voice+'. '+beat.line);expNarration.lang='en-US';expNarration.rate=.9;window.speechSynthesis.speak(expNarration)};$('expFilmNext').focus();}
function expFinishOpening(begin){expStopVoice();cityExperience.ensure(state).openingSeen=true;persist();$('expOpening')?.close();if(begin)lifeContinue();else $('cityScene').focus({preventScroll:true})}
// Returning players keep their current scene. New players choose when to begin the prologue.
const expEntry=$('cityEntranceContinue');if(expEntry&&!$('cityEntrance').hidden&&cityStory.ensure(state).step===0&&!state.cityExperience.openingSeen){const dismiss=expEntry.onclick;expEntry.textContent='Begin the story';expEntry.onclick=()=>{dismiss();expOpening()};$('cityEntranceTitle').textContent='Eight lanterns. One missing song.';$('cityEntrance').querySelector('.city-entrance-content>p').textContent='A family mystery—and a life of your own—awaits in Eldoria.';const skip=document.createElement('button');skip.id='expEntryExplore';skip.textContent='Explore first';skip.onclick=dismiss;$('cityEntrance').querySelector('.city-entrance-choices').append(skip)}
const expJournalBefore=lifeStoryJournal;lifeStoryJournal=function(){expJournalBefore();action('Replay the opening',()=>expOpening())};$('lifeJournal').onclick=lifeStoryJournal;
const expFurnishings=[{id:'teanook',cell:0,x:22,y:78,w:19},{id:'workcorner',cell:1,x:69,y:57,w:22},{id:'herbshelf',cell:2,x:88,y:47,w:15},{id:'reading',cell:3,x:32,y:63,w:22},{id:'windowbox',cell:4,x:48,y:47,w:17},{id:'supper',cell:5,x:61,y:84,w:27}];
function expRenderCottage(){let layer=$('expCottage');if(!layer){layer=document.createElement('div');layer.id='expCottage';$('citySceneArt').after(layer)}layer.replaceChildren();layer.hidden=scene!=='home'||cityInside!=='home'||cityTreehousePorch;if(layer.hidden)return;const l=cityLife.ensure(state);expFurnishings.filter(f=>l.upgrades[f.id]).forEach(f=>{const u=cityLife.upgrades.find(u=>u.id===f.id),b=document.createElement('button');b.className='exp-furniture';b.dataset.project=f.id;b.setAttribute('aria-label','Use '+u.name);b.title=u.name;b.style.cssText='left:'+f.x+'%;top:'+f.y+'%;width:'+f.w+'%;';const sprite=document.createElement('span');sprite.className='exp-furniture-sprite';sprite.style.backgroundPosition=(f.cell%3)*50+'% '+Math.floor(f.cell/3)*100+'%';const label=document.createElement('small');label.textContent=u.name;b.append(sprite,label);b.addEventListener('pointerdown',e=>e.stopPropagation());b.onclick=e=>{e.stopPropagation();expUseProject(f.id)};layer.append(b)});}
function expUseProject(id){if(scene!=='home'||cityInside!=='home'||!cityLife.ensure(state).upgrades[id])return;const u=cityLife.upgrades.find(u=>u.id===id);if(id==='teanook'){lifeGame('tea');return}if(id==='reading'){comfortReadStory(0);return}if(id==='windowbox'){garden();return}if(id==='supper'){lifeFriend('pip');return}const puzzle=id==='workcorner'?'stitch':'herbs';lifePuzzle(puzzle,u.name+' · a little practice',a=>{if(!cityLife.check(puzzle,a))return{ok:false,reason:cityLife.P[puzzle].hint};return{ok:true,title:id==='workcorner'?'Your stitches hold beautifully.':'The moonleaf is ready for the drying rack.'}})}
const expDrawBefore=cityDraw;cityDraw=function(){expDrawBefore();expRenderCottage()};comfortDraw=cityDraw;
const expActionsBefore=cityBuildActions;cityBuildActions=function(){expActionsBefore();if(scene==='home'&&cityInside==='home'){const l=cityLife.ensure(state);expFurnishings.filter(f=>l.upgrades[f.id]).forEach(f=>{const u=cityLife.upgrades.find(u=>u.id===f.id);cityCard(u.name,'Your finished project is placed in the cottage. Use it whenever you visit.','Enjoy this home project',()=>expUseProject(f.id),'⌂')})}if(!state.cityExperience.openingSeen&&cityStory.ensure(state).step===0)cityCard('The eighth lantern','Experience the opening festival scene and discover why the book calls.','Watch the opening',()=>expOpening(),'✦')};
const expHomeBefore=lifeHome;lifeHome=function(){expHomeBefore();if(scene==='home'&&cityInside==='home'){const note=document.createElement('p');note.textContent='Finished projects appear in your cottage scene. Click a furnished corner to use it.';$('modal').append(note);action('See my furnished cottage',()=>{$('modal').close();cityDraw();$('cityScene').scrollIntoView({block:'start',behavior:'smooth'})})}};
window.ELDORIA_EXPERIENCE={version:1,opening:expOpening,investigate:expInvestigate};
cityDraw();persist();
